CREATE TABLE posts.posts (
    id character varying(255) NOT NULL,
    content text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    status character varying(20) NOT NULL,
    thumbnail_url character varying(500),
    title character varying(255) NOT NULL,
    user_id character varying(255) NOT NULL,
    view_count bigint NOT NULL,
    deleted_at timestamp(6) with time zone,
    CONSTRAINT posts_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'APPROVED'::character varying])::text[])))
);


--
-- Name: reacts; Type: TABLE; Schema: posts; Owner: -
--

CREATE TABLE posts.reacts (
    id character varying(255) NOT NULL,
    post_id character varying(255) NOT NULL,
    type character varying(10) NOT NULL,
    user_id character varying(255) NOT NULL,
    CONSTRAINT reacts_type_check CHECK (((type)::text = ANY ((ARRAY['LIKE'::character varying, 'LOVE'::character varying, 'HAHA'::character varying, 'WOW'::character varying, 'SAD'::character varying, 'ANGRY'::character varying])::text[])))
);


--
-- Name: saved_posts; Type: TABLE; Schema: posts; Owner: -
--

CREATE TABLE posts.saved_posts (
    id character varying(255) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    post_id character varying(255) NOT NULL,
    user_id character varying(255) NOT NULL
);


--
-- Name: flyway_schema_history; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.flyway_schema_history (
    installed_rank integer NOT NULL,
    version character varying(50),
    description character varying(200) NOT NULL,
    type character varying(20) NOT NULL,
    script character varying(1000) NOT NULL,
    checksum integer,
    installed_by character varying(100) NOT NULL,
    installed_on timestamp without time zone DEFAULT now() NOT NULL,
    execution_time integer NOT NULL,
    success boolean NOT NULL
);


--
-- Name: audit_logs; Type: TABLE; Schema: system; Owner: -
--

CREATE TABLE system.audit_logs (
    audit_log_id character varying(255) NOT NULL,
    action character varying(50) NOT NULL,
    created_at timestamp with time zone NOT NULL,
    endpoint character varying(255) NOT NULL,
    http_method character varying(10) NOT NULL,
    ip_address character varying(45),
    resource character varying(100) NOT NULL,
    resource_id character varying(100),
    status_code integer NOT NULL,
    success boolean NOT NULL,
    user_agent character varying(500),
    user_id character varying(255),
    details text
);


--
-- Name: email_recipients; Type: TABLE; Schema: system; Owner: -
--

CREATE TABLE system.email_recipients (
    recipient_id character varying(255) NOT NULL,
    email_id character varying(255) NOT NULL,
    user_id character varying(255),
    to_email character varying(255) NOT NULL,
    status character varying(20) NOT NULL,
    error_message text,
    created_at timestamp(6) with time zone NOT NULL,
    sent_at timestamp(6) with time zone,
    CONSTRAINT email_recipients_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'SENT'::character varying, 'FAILED'::character varying])::text[])))
);


--
-- Name: emails; Type: TABLE; Schema: system; Owner: -
--

CREATE TABLE system.emails (
    email_id character varying(255) NOT NULL,
    type character varying(16) NOT NULL,
    code character varying(64),
    name character varying(150),
    description character varying(500),
    subject text NOT NULL,
    body_html text NOT NULL,
    available_vars character varying(500),
    active boolean DEFAULT true NOT NULL,
    created_by character varying(255),
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    updated_by character varying(255),
    deleted_at timestamp(6) with time zone,
    CONSTRAINT emails_code_only_auto CHECK ((((type)::text = 'AUTO'::text) = (code IS NOT NULL))),
    CONSTRAINT emails_type_check CHECK (((type)::text = ANY ((ARRAY['AUTO'::character varying, 'MANUAL'::character varying])::text[])))
);


--
-- Name: page_visits; Type: TABLE; Schema: system; Owner: -
--

CREATE TABLE system.page_visits (
    visit_id character varying(255) NOT NULL,
    path character varying(255) NOT NULL,
    session_key character varying(64),
    user_id character varying(255),
    ip_address character varying(45),
    created_at timestamp with time zone NOT NULL,
    country_code character varying(2),
    country character varying(100)
);


--
-- Name: permissions; Type: TABLE; Schema: users; Owner: -
--

CREATE TABLE users.permissions (
    permission_id character varying(255) NOT NULL,
    code character varying(100) NOT NULL,
    description character varying(255),
    permission_group character varying(50)
);


--
-- Name: role_permissions; Type: TABLE; Schema: users; Owner: -
--

CREATE TABLE users.role_permissions (
    id character varying(255) NOT NULL,
    permission_id character varying(255) NOT NULL,
    role_id character varying(255) NOT NULL
);


--
-- Name: roles; Type: TABLE; Schema: users; Owner: -
--

CREATE TABLE users.roles (
    role_id character varying(255) NOT NULL,
    description character varying(255),
    role_name character varying(50) NOT NULL,
    deleted_at timestamp(6) with time zone
);


--
-- Name: users; Type: TABLE; Schema: users; Owner: -
--

CREATE TABLE users.users (
    user_id character varying(255) NOT NULL,
    avatar_url character varying(255),
    created_at timestamp with time zone NOT NULL,
    email character varying(100) NOT NULL,
    full_name character varying(100) NOT NULL,
    password character varying(255) NOT NULL,
    role_id character varying(255) NOT NULL,
    user_name character varying(50) NOT NULL,
    verification_token character varying(255),
    verified boolean,
    is_premium boolean DEFAULT false NOT NULL,
    deleted_at timestamp(6) with time zone
);


--
-- Name: user_vocabulary; Type: TABLE; Schema: vocabulary; Owner: -
--

CREATE TABLE vocabulary.user_vocabulary (
    id character varying(255) NOT NULL,
    correct_count integer NOT NULL,
    last_reviewed timestamp with time zone,
    status character varying(255),
    user_id character varying(255) NOT NULL,
    vocab_id character varying(255) NOT NULL,
    CONSTRAINT user_vocabulary_status_check CHECK (((status)::text = ANY ((ARRAY['learning'::character varying, 'mastered'::character varying])::text[])))
);


--
-- Name: vocabulary; Type: TABLE; Schema: vocabulary; Owner: -
--

CREATE TABLE vocabulary.vocabulary (
    vocab_id character varying(255) NOT NULL,
    album_id character varying(255) NOT NULL,
    created_at timestamp with time zone,
    example character varying(255),
    meaning character varying(255) NOT NULL,
    phonetic character varying(255),
    voice_url character varying(255),
    word character varying(100) NOT NULL,
    deleted_at timestamp(6) with time zone
);


--
-- Name: vocabulary_album; Type: TABLE; Schema: vocabulary; Owner: -
--

CREATE TABLE vocabulary.vocabulary_album (
    album_id character varying(255) NOT NULL,
    created_at timestamp with time zone,
    description character varying(255),
    name character varying(100) NOT NULL,
    user_id character varying(255) NOT NULL,
    deleted_at timestamp(6) with time zone
);


